using Murim.Simulation;
namespace Murim.World;
public sealed class WorldState
{
 public GameTime Time{get;}=new(); public WorldEventScheduler Events{get;}=new(); public AutonomousWorldEventSystem AutonomousEvents{get;}=new(); public Dictionary<Guid,Npc>Npcs{get;}=new(); public Dictionary<Guid,Family>Families{get;}=new(); public FamilyLifeSystem FamilyLife{get;}=new(); public AutonomousSocialLifeSystem SocialLife{get;}=new(); public SocialRelationshipSystem Relationships{get;}=new(); public GeographySystem Geography{get;}=new(); public TravelSystem Travel{get;}=new(); public TransportNetworkSystem Transport{get;}=new(); public EnvironmentSystem Environment{get;}=new(); public InformationSystem Information{get;}=new(); public ReputationSystem Reputation{get;}=new(); public ExplorationSystem Exploration{get;}=new(); public PerceptionSystem Perception{get;}=new(); public InventorySystem Inventory{get;}=new(); public CommerceSystem Commerce{get;}=new(); public EmploymentSystem Employment{get;}=new(); public EnterpriseSystem Enterprises{get;}=new(); public ProductionSystem Production{get;}=new(); public LogisticsSystem Logistics{get;}=new(); public MarketSystem Markets{get;}=new(); public BankingSystem Banking{get;}=new(); public SurvivalSystem Survival{get;}=new(); public AgingSystem Aging{get;}=new(); public MedicineSystem Medicine{get;}=new(); public MartialTrainingSystem Martial{get;}=new(); public MartialOrganizationSystem MartialOrganizations{get;}=new(); public MartialMentorshipSystem Mentorships{get;}=new(); public MartialConflictSystem MartialConflicts{get;}=new(); public MartialWarSystem MartialWars{get;}=new(); public MartialTerritorySystem MartialTerritories{get;}=new(); public MartialWarConsequencesSystem MartialWarConsequences{get;}=new(); public ContextualActionSystem ContextualActions{get;}=new(); public BuildingSystem Buildings{get;}=new(); public MerchantArbitrageSystem MerchantArbitrage{get;}=new();
 public int WorldSeed{get;private set;} public Npc? PlayerNpc{get;private set;} public void AddNpc(Npc npc){Npcs[npc.Id]=npc;} public void AddFamily(Family family){Families[family.Id]=family;}
 public void AdvanceMinutes(int minutes){if(minutes<0)throw new ArgumentOutOfRangeException(nameof(minutes));Survival.Advance(this,minutes);var old=Time.Day;Time.AdvanceMinutes(minutes);Events.ProcessDue(this);Logistics.Advance(this);var days=Time.Day-old;for(var i=0L;i<days;i++){foreach(var n in Npcs.Values.Where(n=>n.IsAlive))Aging.AdvanceDays(n,1);Environment.AdvanceDay(this,WorldSeed);Medicine.AdvanceDay(this);FamilyLife.AdvanceDay(this);SocialLife.AdvanceDay(this);Relationships.AdvanceDay(this);Mentorships.AdvanceDay(this);Employment.AdvanceDay(this);Production.AdvanceDay(this);Commerce.AdvanceDay(this);Markets.AdvanceDay(this);Enterprises.AdvanceDay(this);Banking.AdvanceDay(this);MartialConflicts.AdvanceDay(this);MartialWarConsequences.AdvanceDay(this);MartialTerritories.AdvanceDay(this);Buildings.AdvanceDay(this);Logistics.Advance(this);MerchantArbitrage.AdvanceDay(this);AutonomousEvents.EnsureScheduled(this);}}
 public void CreatePlayerAtBirth(int seed,string familyName){WorldSeed=seed;Geography.GenerateStarterRegion(seed);Environment.Initialize(Geography,seed);Buildings.InitializeStarterBuildings(this);MartialOrganizations.RegisterTerritorialAuthorities(this);var grain=Inventory.Register("Grain",ItemCategory.Food,.4,.35);var bread=Inventory.Register("Pain de campagne",ItemCategory.Food,.4,1,true);var water=Inventory.Register("Eau",ItemCategory.Food,1,.2,true);var cloth=Inventory.Register("Tissu simple",ItemCategory.Clothing,.3,2);var medicine=Inventory.Register("Herbes médicinales",ItemCategory.Medicine,.1,3,true);var origin=FamilyLife.RollFamilyOrigin(seed,familyName);AddFamily(origin.Family);AddNpc(origin.Father);AddNpc(origin.Mother);AddNpc(origin.Child);var home=Geography.Locations.Values.First(l=>l.Name=="Village du Berceau");origin.Father.SetLocation(home.Id);origin.Mother.SetLocation(home.Id);origin.Child.SetLocation(home.Id);var homeBuilding=Buildings.Buildings.Values.First(b=>b.LocationId==home.Id&&b.Type==BuildingType.House);homeBuilding.ResidentNpcIds.AddRange(new[]{origin.Father.Id,origin.Mother.Id,origin.Child.Id});origin.Father.EnterBuilding(homeBuilding.Id);origin.Mother.EnterBuilding(homeBuilding.Id);origin.Child.EnterBuilding(homeBuilding.Id);origin.Child.DiscoverLocation(home.Id);foreach(var l in Geography.Locations.Values.Where(l=>l.Type is LocationType.Town or LocationType.Market))origin.Child.DiscoverLocation(l.Id);Relationships.Link(origin.Father.Id,origin.Child.Id,RelationshipType.Parent,.8,.8,.5);Relationships.Link(origin.Mother.Id,origin.Child.Id,RelationshipType.Parent,.8,.8,.5);Relationships.Link(origin.Father.Id,origin.Mother.Id,RelationshipType.Spouse,.6,.8,.5);origin.Child.History.Add("Naissance",0,$"Naît à {home.Name} dans la famille {familyName}.");PlayerNpc=origin.Child;var farm=new Building{Name="Ferme du Berceau",Type=BuildingType.Farmhouse,Access=BuildingAccess.Workers,LocationId=home.Id,Description="Petite exploitation agricole familiale.",Capacity=8,OpenMorning=true,OpenAfternoon=true};Buildings.Add(farm);farm.WorkerNpcIds.Add(origin.Father.Id);var breadHouse=new Building{Name="Fournil du Berceau",Type=BuildingType.Workshop,Access=BuildingAccess.Workers,LocationId=home.Id,Description="Un fournil qui transforme le grain en pain.",Capacity=6,OpenMorning=true,OpenAfternoon=true};Buildings.Add(breadHouse);breadHouse.WorkerNpcIds.Add(origin.Father.Id);var grow=Production.RegisterRecipe("Culture du grain",BuildingType.Farmhouse,1440,10,Array.Empty<ProductionInput>(),new[]{new ProductionOutput{ItemId=grain.Id,Quantity=6}});var bake=Production.RegisterRecipe("Cuisson du pain",BuildingType.Workshop,120,20,new[]{new ProductionInput{ItemId=grain.Id,Quantity=2}},new[]{new ProductionOutput{ItemId=grain.Id,Quantity=2}});Production.RegisterSite("Ferme du Berceau",home.Id,farm.Id,origin.Father.Id,grow.Id,capacity:3);Production.RegisterSite("Fournil du Berceau",home.Id,breadHouse.Id,origin.Father.Id,bake.Id,capacity:2);var shopBuilding=new Building{Name="Échoppe de Lin",Type=BuildingType.Shop,Access=BuildingAccess.Customers,LocationId=home.Id,Description="Une boutique familiale.",Capacity=12,OpenMorning=true,OpenAfternoon=true,OpenEvening=true};Buildings.Add(shopBuilding);var shop=Commerce.AddBusiness("Échoppe de Lin",CommerceType.GeneralStore,home.Id,origin.Father.Id,true,shopBuilding.Id);Commerce.AddStock(shop,bread.Id,12,1.1);Commerce.AddStock(shop,water.Id,20);Commerce.AddStock(shop,cloth.Id,6,1.15);Commerce.AddStock(shop,medicine.Id,4,1.3);Enterprises.Register(this,shop);Employment.Post(this,origin.Father,ProfessionType.Merchant,"Assistant de boutique",Math.Max(.3,origin.Father.Profession.DailyIncome/8),Math.Max(0,origin.Father.Profession.Skill),shop.Id,shopBuilding.Id);Markets.AdvanceDay(this);AutonomousEvents.EnsureScheduled(this);}
}